    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    prompt: { d: "M5.25 6.25 7 8l-1.75 1.75M8.5 10h2.25" },
  },
  branch: {
    a: { d: "M6.25 4a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    b: { d: "M6.25 12a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    c: { d: "M12.25 5a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    trunk: { d: "M5 5.25v5.5" },
    twig: { d: "M11 6.25v.5a3 3 0 0 1-3 3H7.25a2.25 2.25 0 0 0-2.25 1" },
  },
  /* An amount of effort: a dial and its needle. */
  gauge: {
    dial: { d: "M2.75 11.75a5.25 5.25 0 1 1 10.5 0" },
    needle: { d: "M8 11.75l2.5-3.5" },
  },
  /* A panel with its column on the other side: show or hide a side panel at the end. */
  panel: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    rail: { d: "M9.75 2.75 L9.75 13.25" },
  },
  /* What happened to a file: one rounded square, and inside it a plus, a
     dot, a minus or an arrow. They share the square and the bar, so a file
     whose change kind moves morphs only the mark. */
  "diff-added": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    stem: { d: "M8 10.5 L8 5.5" },
  },
  "diff-modified": {
    frame: { d: CHANGE_FRAME },
    dot: { d: "M8 8 L8.01 8", block: true },
  },
  "diff-removed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
  },
  "diff-renamed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    head: { d: "M8.5 6 L10.5 8 L8.5 10" },
  },
} satisfies Record<string, Record<string, Stroke>>;

export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

/* Registered so `ch` resolves once, at .root's font size. */
@property --pagination-slot {
  syntax: "<length>";
  inherits: true;
  initial-value: 32px;
}

@property --pagination-arrow {
  syntax: "<length>";
  inherits: true;
  initial-value: 44px;
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .root {
    --pagination-gap: 4px;
    --pagination-height: var(--ui-control-sm);
    /* Arrows are the small icon button's capsule. Numbers are squares of the
       same height, wider only when the longest page number needs it. The pill
       is one number slot, placed past one arrow: plain arithmetic on these
       two widths, so it always lands exactly on its number. */
    --pagination-arrow: calc(var(--pagination-height) * var(--ui-capsule));
    --pagination-slot: max(var(--pagination-height), calc(var(--pagination-digits, 1) * 1ch + var(--ui-space-3)));
    --pagination-dir: 1;

    display: flex;
    justify-content: center;
    inline-size: 100%;
    max-inline-size: calc(
      2 * var(--pagination-arrow) + var(--pagination-slots, 7) * var(--pagination-slot) + (var(--pagination-slots, 7) + 1) * var(--pagination-gap)
    );
    contain: inline-size;
    /* Before the first measure slots may overflow; the margin keeps touch targets. */
    overflow: clip;
    overflow-clip-margin: var(--ui-space-1);
    /* Must match the small button's label, so `ch` matches the numbers. */
    font: var(--ui-weight-medium) 14px / 1 var(--ui-font-sans);
    font-variant-numeric: tabular-nums;
  }

  :is([dir="rtl"]) .root {
    --pagination-dir: -1;
  }

  .root[data-variant="compact"] {
    justify-content: flex-start;
    align-items: center;
    gap: var(--ui-space-3);
    inline-size: auto;
    max-inline-size: none;
    contain: none;
  }

  .track {
    position: relative;
    contain: layout;
  }

  .list {
    display: flex;
    align-items: center;
    gap: var(--pagination-gap);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .item {
    display: flex;
    flex-shrink: 0;
    /* The same curve as the pill, so a number and the pill moving together stay together. */
    transition:
      translate var(--ui-dur-glide) var(--ui-ease-glide),
      opacity var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @starting-style {
    .root[data-ready] .item {
      opacity: 0;
    }
  }

  /* ---------- Controls ---------- */

  /* Raised to outrank the button's size rules, icon-only included, in any
     load order: the pill's arithmetic needs these exact boxes. */
  .root .list .control.control {
    width: var(--pagination-slot);
    min-width: 0;
    height: var(--pagination-height);
    padding-inline: 0;
    color: var(--ui-muted);
    /* The button's `font` shorthand resets these; numbers sit centered in tabular cells. */
    font-variant-numeric: tabular-nums;
    letter-spacing: normal;
  }

  .root .list .control.control[data-arrow] {
    width: var(--pagination-arrow);
  }

  @media (hover: hover) {
    .control.control:hover:not([aria-current], [aria-disabled]) {
      color: var(--ui-foreground);
    }
  }

  .control.control:active:not([aria-current], [aria-disabled]) {
    color: var(--ui-foreground);
  }

  .control.control:focus-visible {
    color: var(--ui-foreground);
  }

  .item[data-key] .control.control {
    --button-bg-hover: transparent;
    --button-bg-press: transparent;
  }

  .control.control[aria-current] {
    --button-bg-hover: transparent;
    --button-bg-press: transparent;
    color: var(--ui-foreground);
    cursor: default;
  }

  .control.control[aria-disabled] {
    --button-bg-hover: transparent;
    --button-bg-press: transparent;
    opacity: 0.5;
    cursor: default;
  }

  :is([dir="rtl"]) .control svg {
    scale: -1 1;
  }

  /* Past previous, then `index` number slots, so it's placed before script runs. */
  .indicator {
    position: absolute;
    inset-block-start: 0;
    inset-inline-start: 0;
    width: var(--pagination-slot);
    height: var(--pagination-height);
    border-radius: var(--ui-radius-full);
    background: var(--ui-fill-strong);
    translate: calc(
        var(--pagination-dir) *
          (var(--pagination-arrow) + var(--pagination-gap) + var(--pagination-index) * (var(--pagination-slot) + var(--pagination-gap)))
      )
      0;
    pointer-events: none;
    transition: translate var(--ui-dur-glide) var(--ui-ease-glide);
  }

  .root[data-instant] :is(.indicator, .item) {
    transition: none;
  }

  .gap {
    display: grid;
    place-items: center;
    width: var(--pagination-slot);
    height: var(--pagination-height);
    color: var(--ui-subtle);
    cursor: default;
    user-select: none;
  }

  /* ---------- Range text ---------- */

  .summary {
    display: grid;
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-regular);
    line-height: var(--ui-leading-sm);
    white-space: nowrap;
  }

  .sizer,
  .text {
    grid-area: 1 / 1;
  }

  .sizer {
    visibility: hidden;
  }

  .root[data-variant="compact"] .text {
    text-align: end;
  }

  .root[data-fit="text"] .summary {
    padding-inline: var(--ui-space-2);
    text-align: center;
  }

  .range {
    color: var(--ui-foreground);
    font-weight: var(--ui-weight-medium);
  }

  /* The gap and -3px hit area must agree so neighbors' hit areas meet. */
  @media (pointer: coarse) {
    .root {
      --pagination-gap: 6px;
    }
    .root .list .control.control::after {
      content: "";
      position: absolute;
      inset: -3px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .indicator,
    .item {
      transition: none;
    }
  }
}

"use client";

import {
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
  type CSSProperties,
  type ElementType,
  type MouseEvent,
  type ReactNode,
} from "react";
import { Button } from "../button/button";
import { ButtonLink } from "../button/button-link";
import { Icon } from "../icons/icons";
import styles from "./pagination.module.css";

type PaginationProps = Omit<ComponentProps<"nav">, "children"> & {
  /** The current page, counted from 1. */
  page: number;
  /** How many pages there are. Optional when `total` and `pageSize` are given. */
  pageCount?: number;
  /** Rows across every page. */
  total?: number;
  /** Rows on a full page. */
  pageSize?: number;
  /** Called with the page to go to; with `href`, before the link navigates. */
  onPageChange?: (page: number) => void;
  /** Makes every control a link: a function of the page, or a string with `{page}` in it. */
  href?: string | ((page: number) => string);
  /** Your router's link component, used with `href`. Defaults to a plain <a>. */
  as?: ElementType;
  /** `pages` (default) shows page numbers; `compact` shows "1–100 of 5,000". */
  variant?: "pages" | "compact";
  /** Locale for the numbers in the compact range. Defaults to the browser's. */
  locale?: string;
};

type Slot = number | "gap-start" | "gap-end";

/** Always `slots` entries once there are more pages, so the width holds. A gap stands for at least two pages. */
function pageSlots(page: number, count: number, slots: number): Slot[] {
  if (count <= slots) return Array.from({ length: count }, (_, i) => i + 1);
  const siblings = (slots - 5) / 2;
  const run = (from: number, length: number) => Array.from({ length }, (_, i) => from + i);
  if (page <= siblings + 3) return [...run(1, slots - 2), "gap-end", count];
  if (page >= count - siblings - 2) return [1, "gap-start", ...run(count - slots + 3, slots - 2)];
  return [1, "gap-start", ...run(page - siblings, siblings * 2 + 1), "gap-end", count];
}

/** Seven slots where they fit, five where they don't, and below that "Page 3 of 20". */
type Fit = 7 | 5 | 0;

const keyOf = (slot: Slot) => String(slot);

/** Previous, page numbers and next, in a row that keeps its width on every page. */
export function Pagination({
  page: requestedPage,
  pageCount,
  total,
  pageSize,
  onPageChange,
  href,
  as,
  variant = "pages",
  locale,
  className,
  style,
  "aria-label": ariaLabel = "Pagination",
  ...props
}: PaginationProps) {
  const count = Math.max(
    1,
    pageCount ?? (total !== undefined && pageSize ? Math.ceil(total / pageSize) : 1),
  );
  const page = Math.min(Math.max(1, Math.round(requestedPage)), count);
  const compact = variant === "compact";

  const rootRef = useRef<HTMLElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const [fit, setFit] = useState<Fit>(7);
  const slots = compact || fit === 0 ? [] : pageSlots(page, count, fit);
  const current = slots.indexOf(page);

  const [ready, setReady] = useState(false);
  useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  // The nav is capped at its row, so its own width is the room there is.
  useLayoutEffect(() => {
    const root = rootRef.current;
    if (compact || !root) return;
    const measure = () => {
      const style = getComputedStyle(root);
      const slot = parseFloat(style.getPropertyValue("--pagination-slot")) || 32;
      const arrow = parseFloat(style.getPropertyValue("--pagination-arrow")) || 44;
      const gap = parseFloat(style.getPropertyValue("--pagination-gap")) || 0;
      const room = root.getBoundingClientRect().width + 0.5;
      const needs = (n: number) => {
        const shown = Math.min(n, count);
        return 2 * arrow + shown * slot + (shown + 1) * gap;
      };
      setFit(needs(7) <= room ? 7 : needs(5) <= room ? 5 : 0);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    return () => observer.disconnect();
  }, [compact, count]);

  // FLIP from the old slot. A change of fit isn't a move: it lands at once.
  const placed = useRef(new Map<string, number>());
  const lastFit = useRef(fit);
  useLayoutEffect(() => {
    const root = rootRef.current;
    const list = listRef.current;
    if (!root || !list) return;
    const refit = lastFit.current !== fit;
    lastFit.current = fit;
    const animate = ready && !refit && !matchMedia("(prefers-reduced-motion: reduce)").matches;

    const next = new Map<string, number>();
    const moving: [HTMLElement, number][] = [];
    for (const el of list.querySelectorAll<HTMLElement>("[data-key]")) {
      const x = el.offsetLeft;
      const was = placed.current.get(el.dataset.key!);
      next.set(el.dataset.key!, x);
      if (animate && was !== undefined && was !== x) {
        const shown = parseFloat(getComputedStyle(el).translate) || 0;
        moving.push([el, was - x + shown]);
      }
    }
    placed.current = next;

    if (moving.length) {
      for (const [el, dx] of moving) {
        el.style.transition = "none";
        el.style.translate = `${dx}px 0`;
      }
      // Lay out the starting point before letting the transition run.
      void list.offsetWidth;
      for (const [el] of moving) {
        el.style.transition = "";
        el.style.translate = "";
      }
    }

    if (refit) {
      root.dataset.instant = "";
      // Style the new place now, so re-enabling transitions next frame animates nothing.
      void root.offsetWidth;
      const frame = requestAnimationFrame(() => delete root.dataset.instant);
      return () => cancelAnimationFrame(frame);
    }
  });

  const numbers = useMemo(() => new Intl.NumberFormat(locale), [locale]);

  const target = (p: number) => (typeof href === "function" ? href(p) : href!.replaceAll("{page}", String(p)));

  function control(p: number, label: string, children: ReactNode, state: { current?: boolean; disabled?: boolean; arrow?: boolean } = {}) {
    const inert = state.current || state.disabled;
    const common = {
      variant: "ghost" as const,
      size: "sm" as const,
      className: styles.control,
      "aria-label": label,
      "aria-current": state.current ? ("page" as const) : undefined,
      // Still focusable at the ends, so focus stays on Next instead of dropping to the page.
      "aria-disabled": state.disabled || undefined,
      // Previous and next are capsules; page numbers are squares.
      "data-arrow": state.arrow || undefined,
    };

    if (href !== undefined) {
      const onClick = (event: MouseEvent<HTMLAnchorElement>) => {
        if (state.disabled) {
          event.preventDefault();
          return;
        }
        if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
        if (state.current) {
          event.preventDefault();
          return;
        }
        onPageChange?.(p);
      };
      // A control that's off still links to this page, so it keeps its href and focus.
      return (
        <ButtonLink as={as} href={target(state.disabled ? page : p)} onClick={onClick} {...common}>
          {children}
        </ButtonLink>
      );
    }

    return (
      <Button onClick={() => !inert && onPageChange?.(p)} {...common}>
        {children}
      </Button>
    );
  }

  const previous = control(page - 1, "Previous page", <Icon name="chevron-left" />, { disabled: page <= 1, arrow: true });
  const nextPage = control(page + 1, "Next page", <Icon name="chevron-right" />, { disabled: page >= count, arrow: true });

  if (compact) {
    const size = pageSize ?? 0;
    const rows = total ?? 0;
    const from = rows === 0 ? 0 : (page - 1) * size + 1;
    const to = Math.min(page * size, rows);
    const widestFrom = rows === 0 ? 0 : (count - 1) * size + 1;
    const known = total !== undefined && pageSize !== undefined;
    const range = (a: number, b: number, widest = false) =>
      known ? (
        <>
          <span className={styles.range}>
            {a === b && !widest ? numbers.format(a) : `${numbers.format(a)}–${numbers.format(b)}`}
          </span>{" "}
          of {numbers.format(rows)}
        </>
      ) : (
        <>
          Page <span className={styles.range}>{numbers.format(a)}</span> of {numbers.format(count)}
        </>
      );

    return (
      <nav
        ref={rootRef}
        aria-label={ariaLabel}
        className={className ? `${styles.root} ${className}` : styles.root}
        data-variant="compact"
        style={style}
        {...props}
      >
        {/* The widest range holds the cell open, so the buttons never move. */}
        <p className={styles.summary} aria-live="polite" aria-atomic="true">
          <span className={styles.sizer} aria-hidden="true">
            {known ? range(widestFrom, rows, true) : range(count, count)}
          </span>
          <span className={styles.text}>{known ? range(from, to) : range(page, count)}</span>
        </p>
        <ul ref={listRef} className={styles.list}>
          <li className={styles.item}>{previous}</li>
          <li className={styles.item}>{nextPage}</li>
        </ul>
      </nav>
    );
  }

  const status = `Page ${page} of ${count}`;
  return (
    <nav
      ref={rootRef}
      aria-label={ariaLabel}
      className={className ? `${styles.root} ${className}` : styles.root}
      data-variant="pages"
      data-fit={fit === 0 ? "text" : fit}
      data-ready={ready || undefined}
      style={
        {
          ...style,
          "--pagination-digits": String(count).length,
          "--pagination-slots": Math.min(7, count),
          "--pagination-index": current,
        } as CSSProperties
      }
      {...props}
    >
      <div className={styles.track}>
        {current >= 0 && <span className={styles.indicator} aria-hidden="true" />}
        <ul ref={listRef} className={styles.list}>
          <li className={styles.item}>{previous}</li>
          {slots.map((slot) => (
            <li key={keyOf(slot)} data-key={keyOf(slot)} className={styles.item} aria-hidden={typeof slot === "number" ? undefined : true}>
              {typeof slot === "number" ? (
                control(slot, `Page ${slot}`, slot, { current: slot === page })
              ) : (
                <span className={styles.gap}>…</span>
              )}
            </li>
          ))}
          {fit === 0 && (
            <li className={styles.item} aria-hidden="true">
              <span className={styles.summary}>
                <span className={styles.sizer}>{`Page ${count} of ${count}`}</span>
                <span className={styles.text}>{status}</span>
              </span>
            </li>
          )}
          <li className={styles.item}>{nextPage}</li>
        </ul>
      </div>
      {/* Announces the page: focus stays on the pressed control, which doesn't say it. */}
      <p className={styles.srOnly} aria-live="polite" aria-atomic="true">
        {status}
      </p>
    </nav>
  );
}
